/**
 * Renders copied face-owned Three resources from the exact privately retained saved 32F result.
 * The returned display session is caller-owned and deliberately survives wrapper disposal; no
 * runtime, runner, or strain owner escapes this boundary.
 */
export async function runBetaSkirtCanonicalMediumSavedRuntime32FrameStrainHeatmapV1(
  owner: unknown,
  canvas: HTMLCanvasElement,
): Promise<BetaSkirtCanonicalMediumSavedRuntime32FrameStrainHeatmapResultV1> {
  if (!owner || typeof owner !== 'object' || !weakMapGet)
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-owner-unavailable',
      'A genuine live saved runtime-source owner is required.',
    );
  const record = reflectApply(weakMapGet, owners, [owner]) as OwnerRecord | undefined;
  if (!record || record.disposed)
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-owner-unavailable',
      'A genuine live saved runtime-source owner is required.',
    );
  if (record.heatmapState === 'running')
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-heatmap-in-progress',
      'This saved runtime source is already rendering its one-shot visible strain heatmap.',
    );
  if (record.heatmapState === 'ran')
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-heatmap-consumed',
      'This saved runtime source already rendered its one-shot visible strain heatmap.',
    );
  if (record.heatmapState === 'blocked')
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-heatmap-blocked',
      'This saved runtime source consumed a blocked visible strain heatmap attempt.',
    );
  if (
    record.adapterState !== '32f-ran' ||
    !record.runner32FrameOwner ||
    !record.runner32FrameDisposer ||
    !record.saved32FrameReport
  )
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-32-frame-required',
      'The authenticated saved 32-frame run must complete before visible strain rendering.',
    );
  if (
    record.strainState !== 'ran' ||
    !record.strainOwner ||
    !record.strainDisposer ||
    !record.saved32FrameStrainReport
  )
    return saved32FrameStrainHeatmapFailure(
      'saved-runtime-strain-required',
      'The authenticated saved 32-frame strain diagnostic must complete before visible rendering.',
    );

  record.heatmapState = 'running';
  let lateSession: BetaSkirtCanonicalMediumSavedWebgpu32FrameStrainHeatmapSessionV1 | null = null;
  try {
    const adapter = await import(
      './beta-skirt-canonical-medium-saved-webgpu-32-frame-strain-heatmap-adapter-v1'
    );
    const beforeRender = reflectApply(weakMapGet, owners, [owner]) as OwnerRecord | undefined;
    if (
      beforeRender !== record ||
      record.disposed ||
      record.adapterState !== '32f-ran' ||
      record.strainState !== 'ran' ||
      record.heatmapState !== 'running'
    )
      return saved32FrameStrainHeatmapFailure(
        'saved-runtime-became-stale',
        'Saved runtime source became stale before visible strain rendering.',
      );
    const result =
      await adapter.createBetaSkirtCanonicalMediumSavedWebgpu32FrameStrainHeatmapAdapterV1(
        canvas,
        record.baseRuntimeSourceOwner as BetaSkirtCanonicalMediumWebgpuRuntimeSourceOwnerV1,
        record.runner32FrameOwner,
        record.strainOwner,
      );
    if (!result.ok)
      throw new TypeError(
        `Saved 32-frame visible strain heatmap blocked: ${result.code}: ${result.detail}`,
      );
    lateSession = result.session;
    const afterRender = reflectApply(weakMapGet, owners, [owner]) as OwnerRecord | undefined;
    if (
      afterRender !== record ||
      record.disposed ||
      record.adapterState !== '32f-ran' ||
      record.strainState !== 'ran' ||
      record.heatmapState !== 'running'
    ) {
      result.session.dispose();
      lateSession = null;
      return saved32FrameStrainHeatmapFailure(
        'saved-runtime-became-stale',
        'Saved runtime source became stale during visible strain rendering.',
      );
    }
    const report = await authenticateSaved32FrameStrainHeatmapReport(
      record.snapshot,
      (record.baseRuntimeSourceOwner as BetaSkirtCanonicalMediumWebgpuRuntimeSourceOwnerV1).report,
      record.runner32FrameOwner.report,
      record.saved32FrameReport,
      record.strainOwner.report,
      record.saved32FrameStrainReport,
      result.report,
    );
    const afterReceipt = reflectApply(weakMapGet, owners, [owner]) as OwnerRecord | undefined;
    if (
      afterReceipt !== record ||
      record.disposed ||
      record.adapterState !== '32f-ran' ||
      record.strainState !== 'ran' ||
      record.heatmapState !== 'running'
    ) {
      result.session.dispose();
      lateSession = null;
      return saved32FrameStrainHeatmapFailure(
        'saved-runtime-became-stale',
        'Saved runtime source became stale while sealing genuine visible strain evidence.',
      );
    }
    record.heatmapState = 'ran';
    lateSession = null;
    return objectFreeze({
      ok: true as const,
      execution: objectFreeze({ session: result.session, adapterReport: result.report, report }),
      heatmapSessionOwnershipTransferredToCaller: true as const,
    });
  } catch (error) {
    lateSession?.dispose();
    const current = reflectApply(weakMapGet, owners, [owner]) as OwnerRecord | undefined;
    if (current === record && !record.disposed && record.heatmapState === 'running')
      record.heatmapState = 'blocked';
    return saved32FrameStrainHeatmapFailure(
      current === record && !record.disposed
        ? 'saved-runtime-heatmap-blocked'
        : 'saved-runtime-became-stale',
      error instanceof Error ? error.message : 'Saved visible strain rendering failed closed.',
    );
  }
}

